//				AdditionalLitellmParams: pulumi.StringMap{
//					"use_fine_tune":          pulumi.String("true"),
//					"max_context":            pulumi.String("16384"),
//					"scale":                  pulumi.String("0.75"),
//					"note":                   pulumi.String("for testing"),
//					"complex_config":         pulumi.String("{\"nested\": {\"value\": 42}}"),
